<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {useI18n} from 'vue-i18n'
import {api,write,errorMessage} from '../lib/api'
import {formatValue,unit,state} from '../lib/state'
import {SnapshotGate} from '../lib/requests'
import {bounds,center,clone,movePolygon,resizePolygon,snapPoint,validPolygon,PlanHistory,pointInside} from '../lib/geometry'
import type {Floorplan,Sensor,Point} from '../lib/types'
import Plan from '../components/Plan.vue'
import Icon from '../components/Icon.vue'
import Notice from '../components/Notice.vue'
const {t}=useI18n()
const plan=ref<Floorplan|null>(null),sensors=ref<Sensor[]>([]),baseline=ref(''),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),selected=ref(''),selectedSensor=ref(''),editingRoom=ref(true),vertex=ref(-1),tool=ref<'select'|'draw'|'pan'>('select'),draft=ref<Point[]>([]),grid=ref(true),snap=ref(true),step=ref(.25),roomWidth=ref(1),roomHeight=ref(1)
const previewGate=new SnapshotGate(),saveGate=new SnapshotGate()
const undoStack=reactive(new PlanHistory()),viewport=reactive({x:-.5,y:-.5,w:12,h:10})
const imported=ref<Floorplan|null>(null),importOpen=ref(false),importText=ref(''),preview=ref<{valid:boolean;rooms:number;sensors:number;warnings:string[]}|null>(null),previewBusy=ref(false),file=ref<HTMLInputElement|null>(null)
const dirty=computed(()=>!!plan.value&&JSON.stringify(plan.value)!==baseline.value)
const currentRoom=computed(()=>plan.value?.rooms.find(r=>r.id===selected.value))
const currentMarker=computed(()=>plan.value?.sensors.find(s=>s.sensor_id===selectedSensor.value))
function selectionKey(){return 'sensogrid.editor.sensor.'+(state.auth?.user?.username??'local')+'.'+(plan.value?.id??'home')}
watch(selectedSensor,id=>{if(!plan.value)return;try{if(id)sessionStorage.setItem(selectionKey(),id);else sessionStorage.removeItem(selectionKey())}catch{/* Selection still works without browser storage. */}})
function restoreSelection(){try{const id=sessionStorage.getItem(selectionKey()),marker=plan.value?.sensors.find(value=>value.sensor_id===id);if(marker&&sensors.value.some(value=>value.id===id)){selectedSensor.value=id!;selected.value=marker.room_id??'';editingRoom.value=false}}catch{/* Browser storage unavailable. */}}
const viewBox=computed(()=>[viewport.x,viewport.y,viewport.w,viewport.h].join(' '))
watch(currentRoom,room=>{if(room){const b=bounds(room.polygon);roomWidth.value=+b.width.toFixed(2);roomHeight.value=+b.height.toFixed(2)}},{deep:true})
watch(importText,()=>{preview.value=null;imported.value=null})
function resetView(){if(!plan.value)return;Object.assign(viewport,{x:-.5,y:-.5,w:plan.value.width+1,h:plan.value.height+1})}
async function load(){loading.value=true;error.value='';try{[plan.value,sensors.value]=await Promise.all([api<Floorplan>('/floorplan'),api<Sensor[]>('/sensors')]);baseline.value=JSON.stringify(plan.value);undoStack.clear();restoreSelection();resetView()}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function checkpoint(){if(plan.value)undoStack.push(plan.value);message.value=''}
function undo(){if(tool.value==='draw'&&draft.value.length){draft.value.pop();return}if(plan.value){const prev=undoStack.undo(plan.value);if(prev)plan.value=prev}vertex.value=-1}
function redo(){if(plan.value){const next=undoStack.redo(plan.value);if(next)plan.value=next}vertex.value=-1}
let fieldBefore:Floorplan|null=null
function beginFieldEdit(){if(plan.value)fieldBefore=clone(plan.value)}
function endFieldEdit(){fieldBefore=null}
function checkpointField(){if(fieldBefore){undoStack.push(fieldBefore);fieldBefore=null}message.value=''}
function roomName(value:string){if(!currentRoom.value||currentRoom.value.name===value)return;checkpointField();currentRoom.value.name=value}
function planName(value:string){if(!plan.value||plan.value.name===value)return;checkpointField();plan.value.name=value}
function dimension(key:'width'|'height',value:number){if(!plan.value||!Number.isFinite(value)||value<=0)return;const width=key==='width'?value:plan.value.width,height=key==='height'?value:plan.value.height;if(plan.value.rooms.some(r=>!validPolygon(r.polygon,width,height))||plan.value.sensors.some(s=>s.x>width||s.y>height)){error.value=t('invalidGeometry');return}if(plan.value[key]===value)return;checkpointField();plan.value[key]=value;error.value='';resetView()}
function finish(){if(!plan.value)return;if(!validPolygon(draft.value,plan.value.width,plan.value.height)){error.value=t('invalidGeometry');return}checkpoint();const id=crypto.randomUUID();plan.value.rooms.push({id,name:t('newRoom')+' '+(plan.value.rooms.length+1),polygon:clone(draft.value)});selected.value=id;editingRoom.value=true;draft.value=[];tool.value='select';error.value=''}
function removeRoom(){if(!plan.value||!selected.value||!confirm(t('confirmDelete')))return;checkpoint();plan.value.rooms=plan.value.rooms.filter(r=>r.id!==selected.value);plan.value.sensors.forEach(s=>{if(s.room_id===selected.value)s.room_id=null});selected.value='';vertex.value=-1}
function resize(){if(!currentRoom.value||!plan.value)return;const polygon=resizePolygon(currentRoom.value.polygon,roomWidth.value,roomHeight.value);if(!validPolygon(polygon,plan.value.width,plan.value.height)){error.value=t('invalidGeometry');return}const b=bounds(currentRoom.value.polygon);checkpoint();for(const marker of plan.value.sensors.filter(s=>s.room_id===currentRoom.value!.id)){marker.x=b.x+(marker.x-b.x)*roomWidth.value/b.width;marker.y=b.y+(marker.y-b.y)*roomHeight.value/b.height}currentRoom.value.polygon=polygon;error.value=''}
function addVertex(){if(!currentRoom.value)return;checkpoint();const polygon=currentRoom.value.polygon,index=vertex.value>=0?vertex.value:polygon.length-1,a=polygon[index]!,b=polygon[(index+1)%polygon.length]!;polygon.splice(index+1,0,[(a[0]+b[0])/2,(a[1]+b[1])/2]);vertex.value=index+1}
function removeVertex(){if(!currentRoom.value||vertex.value<0||!plan.value)return;const polygon=clone(currentRoom.value.polygon);polygon.splice(vertex.value,1);if(!validPolygon(polygon,plan.value.width,plan.value.height)){error.value=t('invalidGeometry');return}checkpoint();currentRoom.value.polygon=polygon;for(const marker of plan.value.sensors.filter(s=>s.room_id===currentRoom.value!.id)){if(!pointInside([marker.x,marker.y],polygon)){const c=center(polygon);marker.x=c[0];marker.y=c[1]}}vertex.value=-1}
function placeSensor(id:string){
 if(!plan.value)return
 if(!id){editingRoom.value=true;return}
 const room=currentRoom.value,targetRoom=editingRoom.value?room:undefined
 selectedSensor.value=id;editingRoom.value=false
 const existing=plan.value.sensors.find(s=>s.sensor_id===id)
 if(existing){
  if(targetRoom&&existing.room_id!==targetRoom.id)assignSensor(targetRoom.id)
  else selected.value=existing.room_id??''
  return
 }
 checkpoint()
 const c=room?center(room.polygon):[plan.value.width/2,plan.value.height/2]
 plan.value.sensors.push({sensor_id:id,room_id:room?.id??null,x:c[0]!,y:c[1]!})
}
function assignSensor(roomId:string){if(!currentMarker.value||!plan.value)return;editingRoom.value=false;checkpoint();const room=plan.value.rooms.find(r=>r.id===roomId);currentMarker.value.room_id=room?.id??null;if(room){const c=center(room.polygon);currentMarker.value.x=c[0];currentMarker.value.y=c[1]}selected.value=roomId}
function removeMarker(){if(!plan.value)return;checkpoint();plan.value.sensors=plan.value.sensors.filter(s=>s.sensor_id!==selectedSensor.value);selectedSensor.value='';editingRoom.value=true}
async function save(){if(!plan.value||busy.value)return;error.value='';busy.value=true;const ticket=saveGate.begin(JSON.stringify(plan.value));try{const saved=await write<Floorplan>('/floorplan',JSON.parse(ticket.snapshot),'PUT');const unchanged=saveGate.matches(ticket,JSON.stringify(plan.value));if(unchanged)plan.value=saved;baseline.value=JSON.stringify(saved);message.value=t(unchanged?'savedPlan':'savedEarlier')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function previewImport(){previewBusy.value=true;error.value='';const ticket=previewGate.begin(importText.value);try{const parsed:unknown=JSON.parse(ticket.snapshot);const result=await write<{valid:boolean;rooms:number;sensors:number;warnings:string[];plan:Floorplan}>('/floorplan/preview',parsed);if(!previewGate.matches(ticket,importText.value))return;imported.value=result.plan;preview.value=result}catch(e){if(previewGate.matches(ticket,importText.value)){preview.value=null;imported.value=null;error.value=errorMessage(e)}}finally{if(previewGate.isLatest(ticket))previewBusy.value=false}}
async function applyImport(){if(!imported.value)return;busy.value=true;error.value='';try{const saved=await write<Floorplan>('/floorplan',imported.value,'PUT');checkpoint();plan.value=saved;baseline.value=JSON.stringify(saved);importOpen.value=false;selected.value='';selectedSensor.value='';editingRoom.value=true;message.value=t('savedPlan');resetView()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function readFile(event:Event){const input=event.target as HTMLInputElement,f=input.files?.[0];if(!f)return;if(f.size>2000000){error.value=t('importInvalid');return}importText.value=await f.text();importOpen.value=true;input.value=''}
async function exportPlan(){error.value='';try{const data=await api<Floorplan>('/floorplan/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sensogrid-floorplan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=errorMessage(e)}}
function svgOf(event:PointerEvent|WheelEvent){const target=event.target as SVGElement;return target instanceof SVGSVGElement?target:target.ownerSVGElement}
function coordinates(event:PointerEvent|WheelEvent):Point {const svg=svgOf(event),ctm=svg?.getScreenCTM();if(!svg||!ctm)return [0,0];const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(ctm.inverse());return [point.x,point.y]}
function bounded(point:Point):Point{const p=plan.value!;const result=snapPoint(point,step.value,snap.value);return [Math.max(0,Math.min(p.width,result[0])),Math.max(0,Math.min(p.height,result[1]))]}
type Drag={kind:'room'|'vertex'|'marker'|'pan'|'pinch';id:string;index:number;origin:Point;before:Floorplan;view:{x:number;y:number;w:number;h:number};screen:Point;distance:number}
let drag:Drag|null=null;const pointers=new Map<number,Point>()
function begin(event:PointerEvent,kind:Drag['kind'],id='',index=-1){if(!plan.value)return;event.preventDefault();pointers.set(event.pointerId,[event.clientX,event.clientY]);const svg=svgOf(event);svg?.setPointerCapture(event.pointerId);if(pointers.size===2){const p=[...pointers.values()];const a=p[0]!,b=p[1]!;if(drag&&JSON.stringify(drag.before)!==JSON.stringify(plan.value))undoStack.push(drag.before);drag={kind:'pinch',id:'',index:-1,origin:coordinates(event),before:clone(plan.value),view:{...viewport},screen:[(a[0]+b[0])/2,(a[1]+b[1])/2],distance:Math.hypot(a[0]-b[0],a[1]-b[1])};return}drag={kind,id,index,origin:coordinates(event),before:clone(plan.value),view:{...viewport},screen:[event.clientX,event.clientY],distance:0}}
function backgroundDown(event:PointerEvent){if(!plan.value)return;if(tool.value==='draw'&&pointers.size===0&&event.isPrimary){draft.value.push(bounded(coordinates(event)));event.preventDefault();return}if(tool.value==='pan'||!event.isPrimary){begin(event,'pan');return}selected.value='';editingRoom.value=true;vertex.value=-1;begin(event,'pan')}
function roomDown(event:PointerEvent,id:string){if(tool.value==='draw'){backgroundDown(event);return}if(tool.value==='pan'){begin(event,'pan');return}selected.value=id;editingRoom.value=true;const assigned=plan.value?.sensors.filter(value=>value.room_id===id)??[];if(!assigned.some(value=>value.sensor_id===selectedSensor.value)&&assigned[0])selectedSensor.value=assigned[0].sensor_id;vertex.value=-1;begin(event,'room',id)}
function vertexDown(event:PointerEvent,id:string,index:number){selected.value=id;editingRoom.value=true;vertex.value=index;begin(event,'vertex',id,index)}
function markerDown(event:PointerEvent,id:string){if(tool.value==='pan'){begin(event,'pan');return}selectedSensor.value=id;editingRoom.value=false;selected.value=plan.value?.sensors.find(s=>s.sensor_id===id)?.room_id??'';vertex.value=-1;begin(event,'marker',id)}
function move(event:PointerEvent){if(!drag||!plan.value||!pointers.has(event.pointerId))return;event.preventDefault();pointers.set(event.pointerId,[event.clientX,event.clientY]);const svg=svgOf(event),rect=svg?.getBoundingClientRect();if(!rect)return;if(drag.kind==='pinch'){const ps=[...pointers.values()];if(ps.length<2)return;const a=ps[0]!,b=ps[1]!,distance=Math.hypot(a[0]-b[0],a[1]-b[1]),scale=Math.max(.2,Math.min(5,drag.distance/Math.max(distance,1))),w=drag.view.w*scale,h=drag.view.h*scale;viewport.x=drag.view.x+(drag.view.w-w)/2-((a[0]+b[0])/2-drag.screen[0])*drag.view.w/rect.width;viewport.y=drag.view.y+(drag.view.h-h)/2-((a[1]+b[1])/2-drag.screen[1])*drag.view.h/rect.height;viewport.w=w;viewport.h=h;return}if(drag.kind==='pan'){viewport.x=drag.view.x-(event.clientX-drag.screen[0])*drag.view.w/rect.width;viewport.y=drag.view.y-(event.clientY-drag.screen[1])*drag.view.h/rect.height;return}const point=bounded(coordinates(event));if(drag.kind==='marker'){const m=plan.value.sensors.find(s=>s.sensor_id===drag!.id);if(m){m.x=point[0];m.y=point[1];m.room_id=plan.value.rooms.find(r=>pointInside(point,r.polygon))?.id??null}return}const room=plan.value.rooms.find(r=>r.id===drag!.id),original=drag.before.rooms.find(r=>r.id===drag!.id);if(!room||!original)return;if(drag.kind==='vertex'){room.polygon=clone(original.polygon);room.polygon[drag.index]=point}else{const delta=snapPoint([point[0]-drag.origin[0],point[1]-drag.origin[1]],step.value,snap.value);room.polygon=movePolygon(original.polygon,delta[0],delta[1],plan.value.width,plan.value.height);const originalMarkers=drag.before.sensors.filter(s=>s.room_id===room.id),oldBounds=bounds(original.polygon),newBounds=bounds(room.polygon);for(const originalMarker of originalMarkers){const m=plan.value.sensors.find(s=>s.sensor_id===originalMarker.sensor_id);if(m){m.x=Math.max(0,Math.min(plan.value.width,originalMarker.x+newBounds.x-oldBounds.x));m.y=Math.max(0,Math.min(plan.value.height,originalMarker.y+newBounds.y-oldBounds.y))}}}}
function up(event:PointerEvent){pointers.delete(event.pointerId);if(!drag||!plan.value)return;if(drag.kind==='vertex'&&plan.value.rooms.some(r=>!validPolygon(r.polygon,plan.value!.width,plan.value!.height))){plan.value=drag.before;error.value=t('invalidGeometry')}else if(JSON.stringify(drag.before)!==JSON.stringify(plan.value)){for(const marker of plan.value.sensors){const room=plan.value.rooms.find(r=>r.id===marker.room_id);if(room&&!pointInside([marker.x,marker.y],room.polygon)){const c=center(room.polygon);marker.x=c[0];marker.y=c[1]}}undoStack.push(drag.before);error.value='';message.value=''}if(!pointers.size||drag.kind!=='pinch')drag=null}
function zoom(factor:number){const w=Math.max(1,Math.min(150,viewport.w*factor)),h=viewport.h*w/viewport.w;viewport.x+=(viewport.w-w)/2;viewport.y+=(viewport.h-h)/2;viewport.w=w;viewport.h=h}
function wheel(event:WheelEvent){event.preventDefault();zoom(event.deltaY>0?1.1:.9)}
function onKey(event:KeyboardEvent){if((event.target as HTMLElement).closest('input,textarea,select'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();if(event.shiftKey)redo();else undo()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void save()}if(event.key==='Escape'){draft.value=[];tool.value='select';selected.value='';selectedSensor.value='';editingRoom.value=true}if(event.key==='Enter'&&tool.value==='draw')finish();if(event.key==='Delete'&&selected.value)removeRoom()}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>!dirty.value||confirm(t('confirmLeave')))
let sensorRefresh:ReturnType<typeof setInterval>|undefined
let refreshingSensors=false
async function refreshSensorValues(){if(refreshingSensors)return;refreshingSensors=true;try{sensors.value=await api<Sensor[]>('/sensors')}catch{/* Preserve current editor changes when offline. */}finally{refreshingSensors=false}}
onMounted(()=>{void load();sensorRefresh=setInterval(()=>void refreshSensorValues(),5000);window.addEventListener('keydown',onKey);window.addEventListener('beforeunload',beforeUnload)})
onUnmounted(()=>{clearInterval(sensorRefresh);window.removeEventListener('keydown',onKey);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<main class="page">
<header class="page-header"><div><div class="eyebrow">SENSOGRID / {{ t('floorplan') }}</div><h1>{{ t('floorplan') }}</h1><p>{{ dirty?t('unsaved'):t('editHelp') }}</p></div><div class="page-actions"><button class="primary" :disabled="busy||!plan||!dirty" @click="save"><Icon name="check" :size="16" />{{ t(busy?'saving':'save') }}</button></div></header>
<Notice v-if="error" kind="error">{{ t('requestFailed') }}<details open><summary>{{ t('details') }}</summary>{{ error }}</details></Notice><Notice v-if="message" kind="success">{{ message }}</Notice><div v-if="loading" class="skeleton plan" :aria-label="t('loading')"></div><template v-else-if="plan">
<div class="editor-toolbar"><div class="segmented"><button v-for="key in (['select','draw','pan'] as const)" :key="key" :class="{active:tool===key}" @click="tool=key;draft=[]">{{ t(key) }}</button></div><div class="page-actions"><button :disabled="!undoStack.canUndo&&!draft.length" :title="t('undo')" :aria-label="t('undo')" @click="undo">↶</button><button :disabled="!undoStack.canRedo" :title="t('redo')" :aria-label="t('redo')" @click="redo">↷</button><label class="check"><input v-model="grid" type="checkbox">{{ t('grid') }}</label><label class="check"><input v-model="snap" type="checkbox">{{ t('snap') }}</label></div></div>
<div v-if="tool==='draw'" class="notice"><span>{{ t('drawHelp') }}</span><button :disabled="draft.length<3" @click="finish">{{ t('finish') }} ({{ draft.length }})</button></div>
<div class="editor-layout">
<div><div class="editor-canvas"><Plan :plan="plan" editable :selected="selected" :grid="grid" :draft="draft" :vertex="vertex" :view-box="viewBox" @background-down="backgroundDown" @room-down="roomDown" @vertex-down="vertexDown" @marker-down="markerDown" @move="move" @up="up" @wheel="wheel" /><div class="canvas-controls"><button :aria-label="t('zoomOut')" @click="zoom(1.2)">−</button><button :aria-label="t('resetView')" @click="resetView">{{ t('reset') }}</button><button :aria-label="t('zoomIn')" @click="zoom(.8)">+</button></div></div><p class="canvas-hint">{{ t('editHelp') }}</p></div>
<aside class="editor-inspector">
<label class="full">{{ t('planName') }}<input :value="plan.name" maxlength="100" @focus="beginFieldEdit" @blur="endFieldEdit" @input="planName(($event.target as HTMLInputElement).value)"></label><div class="form-grid full"><label>{{ t('width') }} (m)<input :value="plan.width" type="number" min="1" max="100" step=".25" @focus="beginFieldEdit" @blur="endFieldEdit" @input="dimension('width',Number(($event.target as HTMLInputElement).value))"></label><label>{{ t('height') }} (m)<input :value="plan.height" type="number" min="1" max="100" step=".25" @focus="beginFieldEdit" @blur="endFieldEdit" @input="dimension('height',Number(($event.target as HTMLInputElement).value))"></label></div><label class="full">{{ t('snap') }} (m)<select v-model.number="step"><option :value=".1">0.1</option><option :value=".25">0.25</option><option :value=".5">0.5</option><option :value="1">1</option></select></label>
<template v-if="currentRoom&&editingRoom"><h3>{{ t('selection') }}</h3><label class="full">{{ t('roomName') }}<input :value="currentRoom.name" maxlength="100" @focus="beginFieldEdit" @blur="endFieldEdit" @input="roomName(($event.target as HTMLInputElement).value)"></label><form class="full" @submit.prevent="resize"><div class="form-grid"><label>{{ t('width') }} (m)<input v-model.number="roomWidth" type="number" min=".1" step=".1" required></label><label>{{ t('height') }} (m)<input v-model.number="roomHeight" type="number" min=".1" step=".1" required></label></div><button style="margin-top:10px" class="wide">{{ t('resize') }}</button></form><button @click="addVertex">{{ t('addVertex') }}</button><button :disabled="vertex<0||currentRoom.polygon.length<=3" @click="removeVertex">{{ t('removeVertex') }}</button><button class="danger full" @click="removeRoom">{{ t('deleteRoom') }}</button></template><p v-else-if="editingRoom" class="helper full">{{ t('selectRoom') }}</p>
<h3>{{ t('sensors') }}</h3><label class="full">{{ t('placeSensor') }}<select v-model="selectedSensor" @change="placeSensor(selectedSensor)"><option value="">{{ t('select') }}</option><option v-for="sensor in sensors" :key="sensor.id" :value="sensor.id">{{ sensor.name }} · {{ formatValue(sensor.available?sensor.temperature:null,'temperature') }} {{ unit('temperature') }} · {{ formatValue(sensor.available?sensor.humidity:null,'humidity') }} %</option></select></label><button v-if="editingRoom&&currentRoom&&selectedSensor&&currentMarker?.room_id!==currentRoom.id" class="full" @click="placeSensor(selectedSensor)">{{ t('placeInRoom',{room:currentRoom.name}) }}</button><template v-if="currentMarker"><label class="full">{{ t('room') }}<select :value="currentMarker.room_id??''" @change="assignSensor(($event.target as HTMLSelectElement).value)"><option value="">{{ t('unassigned') }}</option><option v-for="room in plan.rooms" :key="room.id" :value="room.id">{{ room.name }}</option></select></label><button class="danger full" @click="removeMarker">{{ t('removeMarker') }}</button></template><p v-if="!sensors.length" class="helper full">{{ t('noSensors') }} <RouterLink to="/settings" class="subtle-link">{{ t('settings') }} ↗</RouterLink></p>
</aside>
</div><div class="section"><div class="page-actions"><input ref="file" type="file" accept="application/json,.json" class="visually-hidden" :aria-label="t('import')" @change="readFile"><button @click="file?.click()">{{ t('import') }}</button><button @click="importOpen=true">{{ t('json') }}</button><button @click="exportPlan"><Icon name="download" :size="15" />{{ t('export') }}</button></div><p class="helper">{{ t('importNote') }}</p></div>
</template><button v-else @click="load">{{ t('retry') }}</button>
<Teleport to="body"><div v-if="importOpen" class="modal-backdrop" @pointerdown.self.prevent @keydown.esc="importOpen=false"><section v-dialog class="modal" role="dialog" aria-modal="true" :aria-label="t('preview')"><header class="modal-header"><h2>{{ t('preview') }}</h2><button class="icon-button" :aria-label="t('close')" @click="importOpen=false"><Icon name="close" /></button></header><label>{{ t('json') }}<textarea v-model="importText" :disabled="busy" spellcheck="false" placeholder="{ &quot;schema_version&quot;: 1, ... }"></textarea></label><Notice v-if="error" kind="error">{{ error }}</Notice><template v-if="preview&&imported"><p class="result-count">{{ t('importReady') }} · {{ preview.rooms }} {{ t('roomCount') }} · {{ preview.sensors }} {{ t('sensorCount') }}</p><Plan :plan="imported" editable style="max-height:240px;min-height:180px" /><Notice v-for="warning in preview.warnings" :key="warning">{{ warning }}</Notice><p class="helper">{{ t('importNote') }}</p></template><footer class="modal-footer"><button :disabled="busy||previewBusy||!importText.trim()" @click="previewImport">{{ t(previewBusy?'loading':'preview') }}</button><button v-if="preview&&imported" class="primary" :disabled="busy||previewBusy" @click="applyImport">{{ t(busy?'saving':'applyImport') }}</button></footer></section></div></Teleport>
</main>
</template>
